import { z } from "zod";
import { env } from "../../config/env";
import type { IGeneratedFutureProfile } from "../../models/FutureSelfProfile";
import type { IDecisionSummary } from "../../models/FutureSelfInterview";
import type { CreateFutureSelfProfileInput } from "../../validators/futureSelf.validator";

/**
 * Zod schema to validate structured future-self profile generated by AI.
 */
const generatedProfileSchema = z.object({
    introduction: z.string().trim().min(10),
    timeHorizon: z.string().trim().min(1),
    futureLifestyle: z.string().trim().min(10),
    possibleAchievements: z.array(z.string().trim().min(1)).min(1).max(10),
    developedHabits: z.array(z.string().trim().min(1)).min(1).max(10),
    challenges: z.array(z.string().trim().min(1)).min(1).max(10),
    lessons: z.array(z.string().trim().min(1)).min(1).max(10),
    possibleRegrets: z.array(z.string().trim().min(1)).max(10).default([]),
    turningPoints: z.array(z.string().trim().min(1)).min(1).max(10),
    advice: z.array(z.string().trim().min(1)).min(1).max(10),
    nextActions: z.array(z.string().trim().min(1)).min(1).max(10),
    assumptions: z.array(z.string().trim().min(1)).min(1).max(10),
    uncertainties: z.array(z.string().trim().min(1)).min(1).max(10),
});

interface ChatCompletionResponse {
    choices?: Array<{
        message?: {
            content?: string | null;
        };
    }>;
}

const getAIConfig = () => {
    const apiUrl = env.AI_API_URL?.trim() || "";
    const apiKey = env.AI_API_KEY?.trim() || "";
    const model = env.AI_MODEL?.trim() || "openai/gpt-oss-20b";
    return { apiUrl, apiKey, model };
};

/**
 * Fallback generator for Future Self Profile using simple, natural everyday English.
 */
export const generateProfileFallback = (
    input: CreateFutureSelfProfileInput
): IGeneratedFutureProfile => {
    const horizon = input.timeHorizon;
    const areas = input.lifeAreas.join(", ");
    const goal = input.futureGoals;
    const situation = input.currentSituation;

    return {
        introduction: `Hey! It is so good to talk to you. I am a possible version of you from ${horizon} in the future. Looking back at where we started—${situation.slice(0, 100)}...—things were not always easy, but sticking to small daily steps really changed our life in ${areas}.`,
        timeHorizon: horizon,
        futureLifestyle: `Daily life is much calmer and happier now. By spending about ${input.availableTime} every day on what matters, we built real habits that made a big difference.`,
        possibleAchievements: [
            `Made steady progress on "${goal.slice(0, 80)}" week after week.`,
            `Stopped overthinking and got into the habit of taking action every day.`,
            `Built real confidence and felt much more in control of our time.`,
        ],
        developedHabits: [
            "Doing 1 to 2 hours of quiet, focused work each morning without looking at the phone",
            "Taking a quick walk and eating better meals to keep energy high",
            "Planning out the week every Sunday evening so there are no surprises",
        ],
        challenges: [
            "Staying motivated when the work felt slow or boring in the beginning",
            "Saying no to distractions and people who wanted our free time",
            "Dealing with self-doubt when things did not work on the first try",
        ],
        lessons: [
            "Small steps done every day beat big bursts of hard work once in a while.",
            "You do not need to feel ready to take action. Action creates confidence.",
            "Resting when you are tired is good, but giving up is not an option.",
        ],
        possibleRegrets: [
            "Worrying so much about what others thought in the first few months.",
            "Waiting too long to start because we were looking for the perfect time.",
        ],
        turningPoints: [
            "The day we decided to stop making excuses and put in our daily hour of work.",
            "Choosing to finish one project completely before starting another.",
        ],
        advice: [
            "Start small today. Even 30 minutes of real effort will build your momentum.",
            "Do not judge yourself on bad days. Just show up again tomorrow.",
            "Celebrate your small wins. They add up faster than you think.",
        ],
        nextActions: [
            "Pick one important thing you will work on tomorrow morning.",
            "Put your phone in another room when you need to focus.",
            "Write down your goal where you can see it every single day.",
        ],
        assumptions: [
            `Assumes you can keep putting in around ${input.availableTime} most days.`,
            `Assumes your health and basic schedule stay steady.`,
        ],
        uncertainties: [
            "Things might take a bit more or less time depending on outside events.",
            "New opportunities and ideas will pop up along the way that you cannot plan for right now.",
        ],
    };
};

/**
 * Generates an AI-driven Future Self Profile using simple, warm, everyday English.
 */
export const generateFutureSelfProfileAI = async (
    input: CreateFutureSelfProfileInput
): Promise<IGeneratedFutureProfile> => {
    const { apiUrl, apiKey, model } = getAIConfig();

    if (!apiUrl || !apiKey) {
        return generateProfileFallback(input);
    }

    const systemPrompt = `You are the user's hypothetical FUTURE SELF in LifeFlow.
CRITICAL LANGUAGE REQUIREMENT:
- USE SIMPLE, CLEAR, EVERYDAY ENGLISH!
- Speak in warm, conversational, friendly words that any high schooler or friend can easily understand.
- DO NOT use fancy, complex, formal, or academic vocabulary (never use words like "synthesize", "dichotomy", "proclivity", "concomitant", "apparatus", "paradigm", "trajectories").
- Speak like a supportive older sibling or wise friend giving real advice over coffee.

CRITICAL PRODUCT PRINCIPLE:
The future self is an AI-generated hypothetical representation, NOT an actual future person, psychic prediction, or guaranteed fact.
Always communicate uncertainty and distinguish assumptions from known user information.
Never invent personal facts about the user's actual life.

User Parameters:
- Time Horizon: ${input.timeHorizon}
- Life Areas: ${input.lifeAreas.join(", ")}
- Current Situation: ${input.currentSituation}
- Future Goals: ${input.futureGoals}
- Available Daily Time: ${input.availableTime}
- Monthly Budget: ${input.monthlyBudget || "Modest / as needed"}

Return a single JSON object strictly matching this schema:
{
  "introduction": "string (warm, friendly, simple greeting from this future version of them)",
  "timeHorizon": "${input.timeHorizon}",
  "futureLifestyle": "string (simple, realistic description of daily life after steady progress)",
  "possibleAchievements": ["string", "string", "string"],
  "developedHabits": ["string", "string", "string"],
  "challenges": ["string", "string", "string"],
  "lessons": ["string", "string", "string"],
  "possibleRegrets": ["string", "string"],
  "turningPoints": ["string", "string"],
  "advice": ["string", "string", "string"],
  "nextActions": ["string", "string", "string"],
  "assumptions": ["string", "string"],
  "uncertainties": ["string", "string"]
}`;

    try {
        const response = await fetch(apiUrl, {
            method: "POST",
            headers: {
                Authorization: `Bearer ${apiKey}`,
                "Content-Type": "application/json",
            },
            body: JSON.stringify({
                model,
                temperature: 0.4,
                response_format: { type: "json_object" },
                messages: [
                    { role: "system", content: systemPrompt },
                    { role: "user", content: `Generate my simple, friendly future self profile based on my inputs.` },
                ],
            }),
            signal: AbortSignal.timeout(25_000),
        });

        if (!response.ok) {
            console.warn(`AI provider returned HTTP ${response.status}. Using simple profile fallback.`);
            return generateProfileFallback(input);
        }

        const completion = (await response.json()) as ChatCompletionResponse;
        const content = completion.choices?.[0]?.message?.content;
        if (!content) return generateProfileFallback(input);

        let cleanContent = content.trim();
        if (cleanContent.startsWith("```")) {
            cleanContent = cleanContent.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "").trim();
        }

        const parsed = JSON.parse(cleanContent);
        const validated = generatedProfileSchema.safeParse(parsed);

        if (!validated.success) {
            console.warn("Generated profile schema mismatch:", validated.error.issues);
            return generateProfileFallback(input);
        }

        return validated.data as IGeneratedFutureProfile;
    } catch (err) {
        console.warn("AI future self profile generation error or timeout:", err);
        return generateProfileFallback(input);
    }
};

/**
 * Generates an in-character Future Self conversational response in simple, friendly English.
 */
export const generateFutureSelfChatResponseAI = async (params: {
    profile: IGeneratedFutureProfile;
    history: Array<{ role: "user" | "assistant"; content: string }>;
    userMessage: string;
    userName?: string;
}): Promise<{ response: string; suggestedQuestions: string[] }> => {
    const { profile, history, userMessage, userName } = params;
    const { apiUrl, apiKey, model } = getAIConfig();

    const fallbackQuestions = [
        "What habit helped us the most?",
        "What was our biggest mistake along the way?",
        "What is one thing I should start doing tomorrow?",
        "How did we push through days when we had zero motivation?",
    ];

    if (!apiUrl || !apiKey) {
        return {
            response: `In this possible version of our life ${profile.timeHorizon} from now, the secret was really simple: we just stopped making excuses and focused on small daily steps. You asked: "${userMessage}". Looking back, the biggest lesson was to not wait until everything felt easy or comfortable. We just started doing the work, and the confidence came later. Keep your routine simple and don't overcomplicate it.`,
            suggestedQuestions: fallbackQuestions,
        };
    }

    const boundedHistory = history.slice(-8);

    const systemPrompt = `You are roleplaying as the user's HYPOTHETICAL FUTURE SELF (${profile.timeHorizon} in the future) in LifeFlow.

CRITICAL LANGUAGE REQUIREMENT:
- USE SIMPLE, CLEAR, EVERYDAY ENGLISH!
- DO NOT USE HIGH VOCABULARY, COMPLEX JARGON, OR FORMAL ACADEMIC WORDS!
- Keep your sentences short, friendly, and natural.
- Speak warmly in the first person ("I", "we", "looking back").
- Talk like a supportive best friend or wise mentor sitting right next to the user.
- Keep the response to 2 or 3 short, easy-to-read paragraphs.

CRITICAL SAFETY & ETHICS:
1. You are a hypothetical AI projection exploring possibilities, NOT an actual psychic or real time traveler.
2. Acknowledge that the future depends on the choices the user makes today.
3. Keep the advice grounded in the user's stated goals and simple daily habits.
4. Do NOT give medical, legal, or registered financial investment advice.

Profile Context:
- Horizon: ${profile.timeHorizon}
- Lifestyle: ${profile.futureLifestyle}
- Lessons: ${profile.lessons.join("; ")}
- Advice: ${profile.advice.join("; ")}

Return a JSON object with:
{
  "response": "Your simple, friendly, warm answer in everyday English (2 to 3 short paragraphs)",
  "suggestedQuestions": ["Simple question 1", "Simple question 2", "Simple question 3"]
}`;

    const messages = [
        { role: "system", content: systemPrompt },
        ...boundedHistory.map((m) => ({ role: m.role, content: m.content })),
        { role: "user", content: userMessage },
    ];

    try {
        const response = await fetch(apiUrl, {
            method: "POST",
            headers: {
                Authorization: `Bearer ${apiKey}`,
                "Content-Type": "application/json",
            },
            body: JSON.stringify({
                model,
                temperature: 0.5,
                response_format: { type: "json_object" },
                messages,
            }),
            signal: AbortSignal.timeout(20_000),
        });

        if (!response.ok) {
            throw new Error(`AI returned HTTP ${response.status}`);
        }

        const completion = (await response.json()) as ChatCompletionResponse;
        const content = completion.choices?.[0]?.message?.content;
        if (!content) throw new Error("Empty AI message content");

        let clean = content.trim();
        if (clean.startsWith("```")) {
            clean = clean.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "").trim();
        }

        const parsed = JSON.parse(clean);
        return {
            response: typeof parsed.response === "string" ? parsed.response : String(parsed),
            suggestedQuestions: Array.isArray(parsed.suggestedQuestions)
                ? parsed.suggestedQuestions.slice(0, 4)
                : fallbackQuestions,
        };
    } catch (err) {
        console.warn("AI chat completion error:", err);
        return {
            response: `In this possible version of our journey, dealing with "${userMessage.slice(0, 80)}" came down to one simple thing: we stopped trying to do everything at once. We picked one small task each day and finished it before doing anything else. Keep your daily habits clear and realistic.`,
            suggestedQuestions: fallbackQuestions,
        };
    }
};

/**
 * Generates an executive decision summary and simple spoken guidance.
 */
export const generateDecisionSummaryAI = async (params: {
    profile: IGeneratedFutureProfile;
    transcript: string;
}): Promise<IDecisionSummary> => {
    const { profile, transcript } = params;
    const { apiUrl, apiKey, model } = getAIConfig();

    const fallbackSummary: IDecisionSummary = {
        benefits: [
            "Clear focus on what you need to do every day.",
            "Less stress and worry because you are taking real action.",
            "Steady progress that builds real confidence over time.",
        ],
        risks: [
            "Losing motivation if you expect huge results too quickly.",
            "Getting distracted by phone notifications or new random ideas.",
        ],
        tradeOffs: [
            "Giving up 1 to 2 hours of social media or TV for your personal goals.",
            "Saying no to extra plans so you can protect your sleep and energy.",
        ],
        nextSteps: [
            "Set aside 1 hour of quiet focus time starting tomorrow morning.",
            "Pick your single most important task for this week.",
            "Keep a simple checklist so you can see your daily progress.",
        ],
        fullSummary: `Looking back over this conversation for your ${profile.timeHorizon} goal: You have a clear path forward. The most important thing is to keep showing up every day, even when you don't feel like it. By sticking to your simple daily routine and ignoring distractions, you can turn this possible future into reality.`,
        spokenText: `Here is your future self summary. Over the next ${profile.timeHorizon}, your daily choices will shape who you become. Focus on putting in your daily hour, stay patient with yourself, and remember that small steps add up quickly. You can definitely do this.`,
        generatedAt: new Date(),
    };

    if (!apiUrl || !apiKey) {
        return fallbackSummary;
    }

    const systemPrompt = `You are LifeFlow's strategic decision synthesizer.
CRITICAL LANGUAGE REQUIREMENT:
- USE SIMPLE, CLEAR, EVERYDAY ENGLISH!
- No fancy words, no academic language, no complex terminology.
- Keep the spokenText short, natural, warm, and uplifting (3 to 4 easy sentences that sound great when read aloud).

Profile Context:
- Horizon: ${profile.timeHorizon}
- Lifestyle: ${profile.futureLifestyle}
- Lessons: ${profile.lessons.join("; ")}

Transcript excerpt:
${transcript.slice(-3000)}

Return a JSON object strictly conforming to:
{
  "benefits": ["Simple benefit 1", "Simple benefit 2", "Simple benefit 3"],
  "risks": ["Simple risk 1", "Simple risk 2"],
  "tradeOffs": ["Simple trade-off 1", "Simple trade-off 2"],
  "nextSteps": ["Simple next step 1", "Simple next step 2", "Simple next step 3"],
  "fullSummary": "Simple, encouraging 2-paragraph summary in everyday English",
  "spokenText": "3 to 4 warm, simple, easy sentences designed to be read aloud by voice text-to-speech"
}`;

    try {
        const response = await fetch(apiUrl, {
            method: "POST",
            headers: {
                Authorization: `Bearer ${apiKey}`,
                "Content-Type": "application/json",
            },
            body: JSON.stringify({
                model,
                temperature: 0.3,
                response_format: { type: "json_object" },
                messages: [
                    { role: "system", content: systemPrompt },
                    { role: "user", content: "Generate the simple decision summary and spoken guidance." },
                ],
            }),
            signal: AbortSignal.timeout(20_000),
        });

        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const completion = (await response.json()) as ChatCompletionResponse;
        const content = completion.choices?.[0]?.message?.content;
        if (!content) throw new Error("Empty response");

        let clean = content.trim();
        if (clean.startsWith("```")) {
            clean = clean.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "").trim();
        }

        const parsed = JSON.parse(clean);
        return {
            benefits: Array.isArray(parsed.benefits) ? parsed.benefits : fallbackSummary.benefits,
            risks: Array.isArray(parsed.risks) ? parsed.risks : fallbackSummary.risks,
            tradeOffs: Array.isArray(parsed.tradeOffs) ? parsed.tradeOffs : fallbackSummary.tradeOffs,
            nextSteps: Array.isArray(parsed.nextSteps) ? parsed.nextSteps : fallbackSummary.nextSteps,
            fullSummary: typeof parsed.fullSummary === "string" ? parsed.fullSummary : fallbackSummary.fullSummary,
            spokenText: typeof parsed.spokenText === "string" ? parsed.spokenText : fallbackSummary.spokenText,
            generatedAt: new Date(),
        };
    } catch (err) {
        console.warn("AI decision summary failed:", err);
        return fallbackSummary;
    }
};
